"import csv
from openpyxl import Workbook

INPUT_FILE = "eng_bom_01.csv"
OUTPUT_FILE = "output.xlsx"


def parse_qty(value):
    """Parse a quantity value, returning a float (0.0 if missing/invalid)."""
    if value is None:
        return 0.0
    value = str(value).strip().replace(",", "")
    if not value:
        return 0.0
    try:
        return float(value)
    except ValueError:
        return 0.0


def main():
    # Aggregate quantities per part_no; keep desc/unit from first occurrence
    parts = {}

    with open(INPUT_FILE, newline="", encoding="utf-8-sig") as f:
        reader = csv.DictReader(f)
        # Normalize header names (strip stray whitespace)
        reader.fieldnames = [(name or "").strip() for name in reader.fieldnames]

        for row in reader:
            row = {
                (k or "").strip(): ("" if v is None else str(v).strip())
                for k, v in row.items()
                if k is not None
            }
            part_no = row.get("part_no", "")
            if not part_no:
                continue

            if part_no not in parts:
                parts[part_no] = {
                    "desc": row.get("desc", ""),
                    "unit": row.get("unit", ""),
                    "qty_total": 0.0,
                }

            parts[part_no]["qty_total"] += parse_qty(row.get("qty"))

    # Build output workbook
    wb = Workbook()
    ws = wb.active
    ws.title = "BOM"

    # Header exactly as specified
    ws.append(["part_no", "desc", "qty_total", "unit"])

    # One row per unique part_no, sorted ascending by part_no (string sort)
    for part_no in sorted(parts.keys()):
        rec = parts[part_no]
        qty_total = round(rec["qty_total"])  # round to 0 decimal places -> int
        ws.append([part_no, rec["desc"], qty_total, rec["unit"]])

    wb.save(OUTPUT_FILE)


if __name__ == "__main__":
    main()"
